    /// On the JavaScript target numbers have at most 52 bits, so matching on an
    /// integer segment whose compile-time known size is greater than 52 bits
    /// would silently truncate the value. When that happens we emit a warning.
    ///
    fn check_matched_int_is_in_js_bounds(&mut self, segment: &TypedPatternBitArraySegment) {
        if self.environment.target != Target::JavaScript {
            return;
        }
        if self.current_function.has_javascript_external {
            return;
        }
        if !segment.type_.is_int() {
            return;
        }

        // The warning is only relevant when the segment actually binds a
        // variable, otherwise no value is being extracted and truncated.
        let (Pattern::Assign { .. } | Pattern::Variable { .. }) = segment.value.as_ref() else {
            return;
        };

        let Some(Pattern::BitArraySize(size)) = segment.size() else {
            return;
        };
        let Some(size) = size.compile_time_number() else {
            return;
        };
        let bits = size * segment.unit();

        if bits > BigInt::from(52) {
            self.problems
                .warning(Warning::JavaScriptBitArrayUnsafeInt {
                    location: segment.location,
                    size: bits,
                });
        }
